-- Aero Avante additive data completion, 2026-10-23. No persistent schema change / no code deploy.
-- Target only Frankfurt project uhojhqxnzrolmnopwgpy. Preserve original six UUIDs.
-- Complete-kit research includes four football collaborations in the audit; no invented ITEM/JAN.
begin;
create temporary table aero_verified_input on commit drop as
select * from jsonb_to_recordset($aero$[{"id": "9207b72d-796d-50a5-a69c-ec9b54e4ddb1", "item": "94944", "year": 2013, "name": "Aero Avante Red Special (AR Chassis)", "color": "Red", "typ": "color_special", "src": "https://www.tamiyausa.com/shop/132-rev/jr-aero-avante-red-special/", "src_type": "official_manufacturer", "img": "https://www.tamiya.com/japan_contents/img/usr/item/9/94944/94944_1.jpg", "description": "Red Special complete assembly kit on the AR chassis, with a red body and copper-colored wheels.", "description_it": "Kit completo Red Special su telaio AR, con carrozzeria rossa e cerchi color rame.", "jan": null, "jan_src": null, "status": "discontinued"}, {"id": "fe538d75-4d93-5ae3-b854-0e9a4ba63129", "item": "95024", "year": 2014, "name": "Aero Avante Clear Blue Special (AR Chassis)", "color": "Clear Blue", "typ": "color_special", "src": "https://www.fantasyland.it/wordpress/wp-content/themes/fantasyland/documenti/tamiya/volantini/TA_2014-04.pdf", "src_type": "official_catalog_pdf", "img": "https://cdn.suruga-ya.jp/database/pics_webp/game/603054048.jpg.webp", "description": "Clear blue special complete kit on the AR chassis. Documented in the Italian distributor’s April 2014 catalogue.", "description_it": "Kit completo Clear Blue Special su telaio AR, documentato nel catalogo del distributore italiano di aprile 2014.", "jan": null, "jan_src": null, "status": "unknown"}, {"id": "2577f71d-cfee-5dd6-a3b4-b72f1431059d", "item": "95038", "year": 2014, "name": "Aero Avante Clear Red Special (AR Chassis)", "color": "Clear Red", "typ": "color_special", "src": "https://www.tqrcracing.com/shop/product_view.asp?p_id=9505", "src_type": "trusted_secondary", "img": "https://www.rcjaz.ca/images/tamiya/mini_4wd_series/mini_4wd_car_kit/ms_chassis/b_95038.jpg", "description": "Complete AR-chassis kit with a clear red body and black metal-plated wheels.", "description_it": "Kit completo su telaio AR con carrozzeria rosso trasparente e cerchi metallizzati neri.", "jan": "4950344950386", "jan_src": "https://www.rcjaz.co.uk/display-and-tweak-tamiya-95038-132-aero-avante-clear-red-sp-special-model-kit-p-90067469.html", "status": "unknown"}, {"id": "006db4a7-48cb-54dd-8881-369329ddf11d", "item": "95058", "year": 2014, "name": "Aero Avante Clear Pink Special (AR Chassis)", "color": "Clear Pink", "typ": "color_special", "src": "https://www.tamiyausa.com/shop/132-rev/jr-aero-avante-2/", "src_type": "official_manufacturer", "img": "https://www.rcjaz.ca/images/tamiya/mini_4wd_series/mini_4wd_car_kit/ms_chassis/b_95058.jpg", "description": "Complete AR-chassis kit with a clear pink body, white chassis and fluorescent pink tires.", "description_it": "Kit completo con carrozzeria rosa trasparente, telaio AR bianco e pneumatici rosa fluorescente.", "jan": "4950344950584", "jan_src": "https://www.rcjaz.com/tamiya-95058-132-aero-avante-clear-pink-sp-model-kit-p-90067638.html", "status": "discontinued"}, {"id": "03ffa178-60c9-53c4-a69e-4095040a8332", "item": "95083", "year": 2015, "name": "Aero Avante Clear Orange Special (AR Chassis)", "color": "Clear Orange", "typ": "color_special", "src": "https://www.tamiyausa.com/shop/132-rev/jr-aero-avante-orange-special/", "src_type": "official_manufacturer", "img": "https://cdn.suruga-ya.jp/database/pics_webp/game/603059715.jpg.webp", "description": "Complete AR-chassis special kit with a clear orange body, orange tires and black wheels.", "description_it": "Kit completo speciale su telaio AR con carrozzeria arancione trasparente, pneumatici arancioni e cerchi neri.", "jan": "4950344950836", "jan_src": "https://www.suruga-ya.jp/kaitori/kaitori_detail/603059715", "status": "discontinued"}, {"id": "776c2a2c-b5af-5204-a596-bf15a8224754", "item": "92396", "year": 2018, "name": "Aero Avante OVER DRIVE Special (AR Chassis)", "color": "Clear Blue / SPICA Racing", "typ": "limited", "src": "https://www.tea-league.com/mt/tea/archives/2018/06/_over_drive.html", "src_type": "trusted_secondary", "img": "https://www.tea-league.com/web/overdrive201806001.jpg", "description": "Complete AR-chassis collaboration kit for the film OVER DRIVE, with SPICA Racing markings and silver-plated wheels.", "description_it": "Kit completo su telaio AR realizzato per il film OVER DRIVE, con livrea SPICA Racing e cerchi argentati.", "jan": "4500000190641", "jan_src": "https://www.kaitori-world.jp/products/detail/278035", "status": "unknown"}, {"id": "e0feb82a-a76a-519e-ac91-7f4423cccdb7", "item": "92441", "year": 2023, "name": "ADVAN Aero Avante Limited (AR Chassis)", "color": "Smoke / ADVAN", "typ": "limited", "src": "https://yokohamashop.com/item-detail/1297696", "src_type": "trusted_secondary", "img": "https://cdn.suruga-ya.jp/database/pics_webp/game/603162218.jpg.webp", "description": "Official ADVAN collaboration kit with a smoke body, red AR chassis, white wheels and ADVAN/YOKOHAMA tire markings.", "description_it": "Kit della collaborazione ufficiale ADVAN con carrozzeria fumé, telaio AR rosso, cerchi bianchi e pneumatici marcati ADVAN/YOKOHAMA.", "jan": "4548515000154", "jan_src": "https://yokohamashop.com/item-detail/1297696", "status": "unknown"}, {"id": "70423a5b-d9df-5932-a909-268bed816300", "item": "95655", "year": 2024, "name": "Aero Avante Asia Challenge 2024 Special (AR Chassis)", "color": "White / Blue", "typ": "limited", "src": "https://www.fantasyland.it/tamiya/mini-4wd/modelli-limited-edition-mini4wd/aero-avante-asia-challenge-2024-ar/", "src_type": "trusted_secondary", "img": "https://www.rcjaz.ca/images/tamiya/mini_4wd_series/mini_4wd_car_kit/ar_chassis/b_95655.jpg", "description": "Asia Challenge 2024 complete kit with a white body, blue AR chassis and event-specific stickers.", "description_it": "Kit completo Asia Challenge 2024 con carrozzeria bianca, telaio AR blu e adesivi dedicati all’evento.", "jan": "4950344956555", "jan_src": "https://www.rcjaz.com/tamiya-95655-jr-aero-avante-tmac-2024-special-ar-chassis-mini-4wd-kit-p-34081.html", "status": "discontinued"}, {"id": "a1b91082-8707-5f4c-a2ee-4f43d897d67b", "item": "95210", "year": 2015, "name": "Mini 4WD Starter Pack AR Speed Type — Aero Avante (Limited)", "color": "Blue / Starter Pack 2015", "typ": "limited", "src": "https://hs-tamtam.co.jp/product/detail/112805/", "src_type": "trusted_secondary", "img": "https://www.tamiya.com/japan_contents/img/usr/item/9/95210/95210_1.jpg", "description": "Limited 2015 starter pack containing a complete Aero Avante AR kit, tuning parts and assembly tools. Distinct configured kit from the standard 18701.", "description_it": "Starter Pack limitato del 2015 con kit completo Aero Avante AR, componenti di preparazione e attrezzi. Confezione configurata distinta dal kit standard 18701.", "jan": "4950344952106", "jan_src": "https://hs-tamtam.co.jp/product/detail/112805/", "status": "unknown"}, {"id": "b82d5729-9f76-5194-9fd4-93d49f3a8cca", "item": "18706", "year": 2017, "name": "Mini 4WD Starter Pack AR Speed Type — Aero Avante", "color": "Blue / Starter Pack 2017", "typ": "special", "src": "https://www.tamiya.com/japan/products/18706/index.html", "src_type": "official_manufacturer", "img": "https://www.tamiya.com/japan_contents/img/usr/item/1/18706/18706_1.jpg", "description": "AR Speed Type starter pack containing a complete Aero Avante kit, race-oriented parts and assembly tools.", "description_it": "Starter Pack AR Speed Type con kit completo Aero Avante, componenti da gara e attrezzi di montaggio.", "jan": null, "jan_src": null, "status": "unknown"}]$aero$::jsonb) as t(id uuid,item text,year integer,name text,color text,typ text,src text,src_type text,img text,description text,description_it text,jan text,jan_src text,status text);
do $$begin
 if not exists(select 1 from products where id='c8132bd5-23ee-5f36-b3f6-a75ef0c27ea3' and canonical_item_number='18701') then raise exception 'Aero product precondition failed'; end if;
 if exists(select 1 from aero_verified_input i join product_releases r on r.item_number=i.item where r.id<>i.id) then raise exception 'Existing ITEM must be reconciled, not duplicated'; end if;
end$$;
insert into product_releases(id,product_id,item_number,release_type,edition_type,edition_name,release_year,chassis,barcode_jan,color,description,description_it,discontinued,is_original,data_source,verification_status,production_status,status_checked_at,catalog_visibility,catalog_visibility_reason,catalog_visibility_updated_at)
select id,'c8132bd5-23ee-5f36-b3f6-a75ef0c27ea3',item,case when typ='color_special' then 'Color Special' when item in('95210','18706') then 'Starter Pack' else 'Special Edition' end,typ,name,year,'AR',jan,color,description,description_it,status='discontinued',false,'family_audit_20261023','verified',status,now(),'public','Verified complete-kit identity and exact matched release photograph',now() from aero_verified_input
on conflict(id) do nothing;
insert into release_images(release_id,url,position)
select i.id,i.img,0 from aero_verified_input i where not exists(select 1 from release_images x where x.release_id=i.id and x.url=i.img);
insert into release_sources(release_id,source_type,source_url,verified_fields,checked_at,notes)
select i.id,i.src_type,i.src,array['item_number','edition_name','chassis'],'2026-10-23','Exact complete-kit source. Release year cross-checked in family audit. Unknown dates, rarity and MSRP are not inferred. Image verified visually and through existing Next Image allowlist.' from aero_verified_input i where not exists(select 1 from release_sources x where x.release_id=i.id and x.source_url=i.src);
insert into release_sources(release_id,source_type,source_url,verified_fields,checked_at,notes)
select i.id,'trusted_secondary',i.jan_src,array['barcode_jan'],'2026-10-23','Exact kit identifier; EAN-13 checksum validated. Retail/buyback catalogue used for identity only, never as proof of a completed sale.' from aero_verified_input i where i.jan is not null and not exists(select 1 from release_sources x where x.release_id=i.id and x.source_url=i.jan_src);
insert into release_identifiers(release_id,scheme,value,market,is_primary,verification_status,source_url,checked_at)
select id,'JAN',jan,null,true,'verified',jan_src,'2026-10-23' from aero_verified_input where jan is not null
on conflict(release_id,scheme,value,market) do nothing;
-- Enroll only the ten new identified kits; initial eBay scan once, not recurring cadence reset.
select trackdash_enroll_release_market_scans(id) from aero_verified_input;
update market_scan_queue q set next_scan_at='2000-01-02',updated_at=now()
where q.release_id in(select id from aero_verified_input) and q.source_id=(select id from price_sources where slug='ebay_active_public') and q.enabled and q.last_attempt_at is null;
-- RCJaz provenance trigger may enroll endpoints; policy is still planned. Keep this family parked.
update market_scan_queue q set enabled=false,next_scan_at='2099-01-01',updated_at=now() where release_id in(select id from product_releases where product_id='c8132bd5-23ee-5f36-b3f6-a75ef0c27ea3') and source_id=(select id from price_sources where slug='rcjaz_public');
update market_scan_targets q set enabled=false,next_scan_at='2099-01-01',updated_at=now() where release_id in(select id from product_releases where product_id='c8132bd5-23ee-5f36-b3f6-a75ef0c27ea3') and source_id=(select id from price_sources where slug='rcjaz_public');
-- Ready existing Gandolfi adapter, exact 95655 / EUR / live in-stock page verified.
insert into market_scan_endpoints(release_id,source_id,endpoint_url,parser_kind,exact_release_verified,enabled)
select id,'3b726a23-c149-4d7b-8a10-520b46eee4fa','https://www.modellismogandolfi.com/prodotto/aero-avante-asia-challenge-2024-special-telaio-ar-edizione-limitata/','generic_product_page',true,true from aero_verified_input where item='95655'
on conflict(release_id,source_id,endpoint_url) do nothing;
insert into market_scan_targets(release_id,source_id,enabled,scan_interval_hours,priority,next_scan_at)
select id,'3b726a23-c149-4d7b-8a10-520b46eee4fa',true,672,80,'2000-01-02' from aero_verified_input where item='95655' on conflict(release_id,source_id) do nothing;
insert into market_scan_queue(release_id,source_id,scan_scope,enabled,scan_interval_hours,priority,next_scan_at)
select id,'3b726a23-c149-4d7b-8a10-520b46eee4fa','retail',true,672,80,'2000-01-02' from aero_verified_input where item='95655' on conflict(release_id,source_id,scan_scope) do nothing;
select trackdash_enqueue_market_recompute(id,'new_complete_unbuilt') from aero_verified_input;
commit;
select count(*) total_releases,count(*) filter(where catalog_visibility='public') public_releases from product_releases where product_id='c8132bd5-23ee-5f36-b3f6-a75ef0c27ea3';
